-- intake_working_setup_seed.sql
--
-- T13/T14 + the step merge, for the CLIENT intake form.
--
-- 1. Merges "Role Requirements" into "Working Setup & Budget" and renames the
--    combined step. NOTE: the merge itself was Haider's call, not Rebecca's —
--    she asked for the new FIELDS below, not for the steps to be combined.
--    It is done here rather than by hand so a fresh environment matches.
--
-- 2. Adds the business-hours block Rebecca asked for at 48:15:
--      "what is your time zone of operations as a business? What are your
--       hours as a business? What percentage of these hours do you need the
--       candidate to work? Do you need them to be specific hours? If so, what
--       are the hours?"
--    plus the deal-breaker toggle from 48:15: "a toggle of, is this a deal
--    breaker? Yes or no."
--
-- 3. Replaces the 1–5 urgency SLIDER with the named options Haider proposed
--    at 49:13 ("immediately / within a week / within a month") and Rebecca
--    accepted ("Yeah, I like that. That's good.").
--
--    The old `urgency_scale` is DEACTIVATED, not edited: it already has
--    answers, and Postgres blocks a question_type change once answer_count > 0
--    (trg_block_question_type_change → 409 QUESTION_TYPE_LOCKED). Deactivating
--    and adding a replacement is the documented path
--    (03-INTAKE-FORM-ENGINE §1.5). Historical answers keep rendering from
--    their question_snapshot.
--
-- 4. Deactivates `requires_us_overlap` — the blunt yes/no the new block
--    supersedes. Same reasoning: its answers stay readable.
--
-- Re-runnable: fixed ids + on conflict do nothing.

-- ---------------------------------------------------------------------------
-- 1. Merge the two steps
-- ---------------------------------------------------------------------------
update questions
   set category_id = '00000000-0000-4000-8000-000000000403',
       -- Keep Role Requirements' questions ahead of the working-setup ones.
       sort_order = sort_order
 where category_id = '00000000-0000-4000-8000-000000000402';

update questions
   set sort_order = sort_order + 100
 where category_id = '00000000-0000-4000-8000-000000000403'
   and key in ('budget_range', 'target_start_date', 'hours_per_week', 'additional_context');

update question_categories
   set label = 'Role & Working Setup',
       description = 'What the role needs, the hours, and the budget'
 where id = '00000000-0000-4000-8000-000000000403';

-- The emptied category is deactivated, never deleted: 02 §5 forbids deleting a
-- category that has ever held questions, and its historical answers reference it.
update question_categories
   set is_active = false
 where id = '00000000-0000-4000-8000-000000000402';

-- ---------------------------------------------------------------------------
-- 2. Retire the superseded questions
-- ---------------------------------------------------------------------------
update questions set is_active = false
 where key in ('urgency_scale', 'requires_us_overlap');

-- ---------------------------------------------------------------------------
-- 3. New questions
-- ---------------------------------------------------------------------------
   is_required, sort_order, validation,
   conditional_on_question_id, conditional_operator, conditional_value)
values
  ('00000000-0000-4000-8000-000000000709', '00000000-0000-4000-8000-000000000403', 'hiring_urgency',
   'How urgent is this hire?', null, null,
   'single_select', 'client', true, 110, '{}', null, null, null),

  ('00000000-0000-4000-8000-000000000701', '00000000-0000-4000-8000-000000000403', 'client_business_timezone',
   'What timezone does your business run on?',
   'We match candidates to your working day.', null,
   'single_select', 'client', true, 120, '{}', null, null, null),

  ('00000000-0000-4000-8000-000000000702', '00000000-0000-4000-8000-000000000403', 'client_business_hours_start',
   'Your business day starts at', null, null,
   'single_select', 'client', false, 121, '{}', null, null, null),

  ('00000000-0000-4000-8000-000000000703', '00000000-0000-4000-8000-000000000403', 'client_business_hours_end',
   'Your business day ends at', null, null,
   'single_select', 'client', false, 122, '{}', null, null, null),

  ('00000000-0000-4000-8000-000000000704', '00000000-0000-4000-8000-000000000403', 'overlap_percentage_required',
   'What percentage of those hours do you need them working?',
   'For example, 100 means the whole day; 50 means half of it.', '100',
   'number', 'client', false, 123, '{"min":0,"max":100}', null, null, null),

  ('00000000-0000-4000-8000-000000000705', '00000000-0000-4000-8000-000000000403', 'requires_specific_hours',
   'Do they need to work specific hours?',
   'Rather than any hours that overlap with yours.', null,
