  ('00000000-0000-4000-8000-000000000706', '00000000-0000-4000-8000-000000000403', 'specific_hours_start',
   'Those hours start at', null, null,
   'single_select', 'client', false, 125, '{}',
   '00000000-0000-4000-8000-000000000705', 'is_true', null),

  ('00000000-0000-4000-8000-000000000707', '00000000-0000-4000-8000-000000000403', 'specific_hours_end',
   'Those hours end at', null, null,
   'single_select', 'client', false, 126, '{}',
   '00000000-0000-4000-8000-000000000705', 'is_true', null),

  ('00000000-0000-4000-8000-000000000708', '00000000-0000-4000-8000-000000000403', 'overlap_is_deal_breaker',
